import{_ as t,o,c as r,ag as a}from"./chunks/framework.HG0H2VLS.js";const g=JSON.parse('{"title":"Selector (CC) — figma notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/cc/patterns/Selector/Selector.figma-notes.md","filePath":"public/demos/src/cc/patterns/Selector/Selector.figma-notes.md"}'),d={name:"public/demos/src/cc/patterns/Selector/Selector.figma-notes.md"};function s(i,e,n,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="selector-cc-—-figma-notes" tabindex="-1">Selector (CC) — figma notes <a class="header-anchor" href="#selector-cc-—-figma-notes" aria-label="Permalink to &quot;Selector (CC) — figma notes&quot;">​</a></h1><p><strong>Tier:</strong> Pattern · <strong>Status:</strong> CODE-FIRST (designer, 2026-09-29). <strong>Drawn in Figma 2026-09-30</strong> (<code>3941:23874</code>). Flagged for Figma; check with Mark before any Figma push.</p><p>The record screens&#39; four pickers as one pattern. The mode is <code>data-selector</code> on the overlay:</p><table tabindex="0"><thead><tr><th>Type</th><th>Used by</th><th>Interaction</th></tr></thead><tbody><tr><td><code>single</code></td><td>Section, Creator, Article Step (Import step)</td><td>Click a row to choose it and close. The current value is ticked and pinned to the top on open. <strong>Clear selection</strong> empties the field. The name cell is a <code>&lt;button&gt;</code>, so the keyboard reaches it.</td></tr><tr><td><code>multi</code></td><td>Multi Display, Topics, Countries, Related Authors</td><td>The FilterDropdowns Multi Select Modal. TagBox.js still owns open / Apply; Selector.js adds the name search and the &quot;n selected&quot; count.</td></tr><tr><td><code>media</code></td><td>Thumbnail, Main Image, Alternative Thumbnail, … (every MediaPicker <strong>Edit</strong>)</td><td>The Media Items listing&#39;s grid as a one-pick picker. Click a tile (brand ring + tick), then <strong>Use image</strong>, or double-click the tile. Filters, My media, Upload and Load more are inert (handover). The toolbar <strong>Upload</strong> is secondary. When a search or filter matches nothing, the no-results state shows a <strong>primary Upload</strong> (designer, 2026-09-29): there is nothing to pick, so uploading is the way forward.</td></tr><tr><td><code>sort</code></td><td>Sort Order</td><td><strong>Drag</strong> by the grip (Edit Columns&#39; handle model: draggable only from the grip, and the insertion line is a border). <strong>↑ ↓</strong> moves one place; <strong>⤒ ⤓</strong> moves to the top or bottom; or <strong>type a position</strong> and press Enter. <strong>Search</strong> narrows the list, and drag pauses while it does (a hint says so) because a drop between non-neighbours means nothing. The arrows and positions still work. <strong>This article</strong> is tinted, badged, and scrolled into view on open, and <strong>Jump to this article</strong> brings it back. <strong>Reset</strong> restores the order it opened with; <strong>Cancel</strong> or Escape discards; <strong>Save order</strong> writes the new position number into the field (its placeholder is the default position, 40).</td></tr></tbody></table><h2 id="variations-by-field-builder-parameters-record-markup-py" tabindex="-1">Variations by field (builder parameters, <code>record_markup.py</code>) <a class="header-anchor" href="#variations-by-field-builder-parameters-record-markup-py" aria-label="Permalink to &quot;Variations by field (builder parameters, `record_markup.py`)&quot;">​</a></h2><ul><li><strong>single</strong> takes its <code>columns</code>, <code>facets</code>, search placeholder and a <code>value(row)</code>. The Article Step lookup (Import step) is two columns, Article · Article step, with no facets; the field gets &quot;Step — Article&quot; so search matches either column and two same-named steps stay distinct. Two columns get <code>.selector__table--pair</code>: equal halves that wrap, because both are long free text. A <code>total</code> adds the &quot;Showing n of N&quot; line.</li><li><strong>sort</strong> takes the list noun, the badge label (<code>data-sort-this</code> on the overlay, which the status line reads), and the Jump / Find labels. Rows without an image drop the thumbnail. On Import step the current row is the step being imported, appended last and badged &quot;Importing&quot;.</li></ul><h2 id="why-these-long-list-aids-sort" tabindex="-1">Why these long-list aids (sort) <a class="header-anchor" href="#why-these-long-list-aids-sort" aria-label="Permalink to &quot;Why these long-list aids (sort)&quot;">​</a></h2><p>The live screen is drag-only. With the 73 articles in Insight, moving one article from 40 to 1 is a long drag with auto-scroll. The typed position and the ⤒ ⤓ buttons make that one action. Search finds the item. The pinned-and-scrolled current article removes the hunt, because on a record screen it is almost always the one being placed. The auto-scroll near the list&#39;s edges keeps a long drag possible.</p><h2 id="narrow-≤559-media-the-overlay-is-position-fixed-so-it-is-viewport-sized" tabindex="-1">Narrow (≤559, <code>@media</code>: the overlay is <code>position: fixed</code>, so it is viewport-sized) <a class="header-anchor" href="#narrow-≤559-media-the-overlay-is-position-fixed-so-it-is-viewport-sized" aria-label="Permalink to &quot;Narrow (≤559, `@media`: the overlay is `position: fixed`, so it is viewport-sized)&quot;">​</a></h2><ul><li><strong>Sort:</strong> the thumbnail, ⤒ ⤓ and the grip drop out. HTML5 drag does not exist on touch (<code>(hover: none)</code> hides the grip too), so ↑ ↓ and the typed position are the mobile way. A typed 1 means &quot;top&quot;.</li><li>The footer wraps: the status line first, then the buttons.</li></ul><h2 id="tokens-all-ai" tabindex="-1">Tokens (all <code>--ai-*</code>) <a class="header-anchor" href="#tokens-all-ai" aria-label="Permalink to &quot;Tokens (all `--ai-*`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Token</th></tr></thead><tbody><tr><td>Search cap / basis</td><td><code>--ai-size-7</code> max, <code>--ai-size-5</code> basis (a cap, not a floor)</td></tr><tr><td>Selected row (single), current row (sort)</td><td><code>--ai-surface-brand-soft-extra</code></td></tr><tr><td>Tick, tile ring, drop line, moved flash</td><td><code>--ai-icon-brand</code>, <code>--ai-border-brand</code></td></tr><tr><td>Media modal / sort modal width</td><td><code>--ai-size-12</code> (960) / <code>--ai-size-11</code> (768)</td></tr><tr><td>Scroll region cap</td><td><code>--ai-size-10</code></td></tr><tr><td>Tile min</td><td><code>--ai-size-1</code> (the Media Items grid&#39;s own is <code>--ai-size-2</code>; smaller because a picker wants more choices per screen)</td></tr><tr><td>Sort thumb / position input</td><td><code>--ai-spacing-8</code> square / <code>--ai-spacing-9</code> × <code>--ai-spacing-7</code></td></tr><tr><td>Hint bar</td><td><code>--ai-surface-info-soft</code></td></tr><tr><td>Sort footer Reset (tertiary)</td><td>transparent at rest only; hover / pressed / focus keep the tertiary tokens (designer, 2026-09-29)</td></tr><tr><td>Sort row move buttons (tertiary sm)</td><td><code>--ai-border-secondary</code> border, the listing account chip&#39;s Case B override (designer, 2026-09-29), restated for hover / focus</td></tr></tbody></table><h2 id="needs-figma" tabindex="-1">Needs Figma <a class="header-anchor" href="#needs-figma" aria-label="Permalink to &quot;Needs Figma&quot;">​</a></h2><p>A Selector component set with <code>Type=Single|Multi|Media|Sort</code>. Sort also needs a row sub-component (<code>State=Default|Current|Dragging|Drop-before|Drop-after</code>), the filtered state (grip hidden plus the hint), and a Mobile variant. Media needs a tile (<code>State=Default|Hover|Selected</code>).</p><h2 id="handover" tabindex="-1">Handover <a class="header-anchor" href="#handover" aria-label="Permalink to &quot;Handover&quot;">​</a></h2><p><code>selector-single-source</code>, <code>steps-import-source</code>, <code>selector-media-source</code>, <code>selector-media-upload</code>, <code>selector-sort-order</code> (HANDOVER.md, RecordScreen surface).</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><p>Selector.css, Selector.js. <code>Selector.html</code> is <strong>generated</strong> by <code>src/cc/templates/RecordScreen/_generate.py</code> from the same builders as ArticleEdit (<code>record_markup.py</code>): edit the <code>.py</code>, not the HTML.</p><h2 id="figma-build-2026-09-30" tabindex="-1">Figma build 2026-09-30 <a class="header-anchor" href="#figma-build-2026-09-30" aria-label="Permalink to &quot;Figma build 2026-09-30&quot;">​</a></h2><p>View &amp; Edit kit, &quot;Code-first components&quot;: <strong>Selector <code>3941:23874</code></strong> — Type=Single <code>3941:23050</code>, Paired <code>3941:23172</code> (Article · Article step), Multi <code>3941:23243</code>, Media <code>3941:23429</code>, Sort <code>3941:23622</code> (960 wide; Sort 768). Built from <strong>SelectorRow <code>3940:23025</code></strong> (Type Single | Paired × State Default | Selected), <strong>SelectorTile <code>3940:23047</code></strong> (Default | Selected) and <strong>SelectorSortRow <code>3940:23132</code></strong> (Default | Current). The modal shell copies the DS Modal&#39;s fill / border / radius / shadow; header, toolbar (SearchInput with its button hidden, Filter Item chips), table, footer are composed. Not drawn: the filtered-sort hint, the drag / drop-line states, the empty (no results) state, and Mobile.</p>',20)])])}const u=t(d,[["render",s]]);export{g as __pageData,u as default};
